# Web Audio API Sound Generator Helper
def play_sound(sound_type):
    if not st.session_state.get("sound_enabled", True):
        return
    
    if sound_type == "correct":
        js_code = """
        <script>
        (function() {
            try {
                const ctx = new (window.AudioContext || window.webkitAudioContext)();
                const now = ctx.currentTime;
                [523.25, 659.25, 783.99].forEach((freq, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.value = freq;
                    gain.gain.setValueAtTime(0.2, now + i*0.12);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + i*0.12 + 0.35);
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.start(now + i*0.12);
                    osc.stop(now + i*0.12 + 0.35);
                });
            } catch(e) {}
        })();
        </script>
        """
        st.components.v1.html(js_code, height=0)
    elif sound_type == "wrong":
        js_code = """
        <script>
        (function() {
            try {
                const ctx = new (window.AudioContext || window.webkitAudioContext)();
                const now = ctx.currentTime;
                [220.0, 180.0].forEach((freq, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sawtooth';
                    osc.frequency.value = freq;
                    gain.gain.setValueAtTime(0.25, now + i*0.15);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + i*0.15 + 0.3);
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.start(now + i*0.15);
                    osc.stop(now + i*0.15 + 0.3);
                });
            } catch(e) {}
        })();
        </script>
        """
        st.components.v1.html(js_code, height=0)
    elif sound_type == "victory":
        js_code = """
        <script>
        (function() {
            try {
                const ctx = new (window.AudioContext || window.webkitAudioContext)();
                const now = ctx.currentTime;
                const notes = [523.25, 659.25, 783.99, 1046.50];
                notes.forEach((freq, i) => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'triangle';
                    osc.frequency.value = freq;
                    gain.gain.setValueAtTime(0.3, now + i*0.18);
                    gain.gain.exponentialRampToValueAtTime(0.001, now + i*0.18 + 0.6);
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.start(now + i*0.18);
                    osc.stop(now + i*0.18 + 0.6);
                });

                // Prison bars drop clank sound at 0.3s
                setTimeout(() => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'square';
                    osc.frequency.setValueAtTime(140, ctx.currentTime);
                    osc.frequency.exponentialRampToValueAtTime(35, ctx.currentTime + 0.25);
                    gain.gain.setValueAtTime(0.4, ctx.currentTime);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.3);
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.start(); osc.stop(ctx.currentTime + 0.3);
                }, 300);

                // Stamp slam sound at 1.1s
                setTimeout(() => {
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sawtooth';
                    osc.frequency.setValueAtTime(90, ctx.currentTime);
                    osc.frequency.exponentialRampToValueAtTime(25, ctx.currentTime + 0.35);
                    gain.gain.setValueAtTime(0.5, ctx.currentTime);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.4);
                    osc.connect(gain); gain.connect(ctx.destination);
                    osc.start(); osc.stop(ctx.currentTime + 0.4);
                }, 1100);
            } catch(e) {}
        })();
        </script>
        """
        st.components.v1.html(js_code, height=0)

# Function to render Elice arrest card with animated bars falling down
def render_elice_arrest_card():
    img_src = ""
    # Check for local image file
    for fn in ["elice_animation_preview.png", "elice.png", "Elice Escape.png", "elice escape.png"]:
        if os.path.exists(fn):
            try:
                with open(fn, "rb") as f:
                    b64_data = base64.b64encode(f.read()).decode()
                    ext = fn.split('.')[-1].lower()
                    mime = "jpeg" if ext in ["jpg", "jpeg"] else "png"
                    img_src = f"data:image/{mime};base64,{b64_data}"
                    break
            except Exception:
                pass
    
    if not img_src and ELICE_IMAGE_B64:
        img_src = f"data:image/jpeg;base64,{ELICE_IMAGE_B64}"

    if img_src:
        arrest_html = f"""
        <div class="arrest-card-container">
            <div class="arrest-header">ELICE "SKUGGAN" — ARRESTERAD</div>
            <div class="arrest-image-wrapper">
                <img src="{img_src}" alt="Elice Skuggan" />
                <div class="jail-overlay">
                    <div class="jail-crossbar-top"></div>
                    <div class="jail-bar"></div>
                    <div class="jail-bar"></div>
                    <div class="jail-bar"></div>
                    <div class="jail-bar"></div>
                    <div class="jail-bar"></div>
                    <div class="jail-bar"></div>
                    <div class="jail-crossbar-bottom"></div>
                </div>
                <div class="arrest-stamp">LÅST INOM LÅS OCH BOM</div>
            </div>
            <div class="arrest-footer">FALLET ÄR AVSLUTAT & APPARATEN SÄKRAD</div>
        </div>
        """
        st.markdown(arrest_html, unsafe_allow_html=True)
    else:
        st.warning("Bilden på Elice kunde inte hittas. Se till att elice_animation_preview.png ligger i mappen.")

