# Helper function to validate codes flexibly
def is_code_correct(user_input, target_code):
    u = user_input.strip().upper()
    t = target_code.strip().upper()
    if t == "ELICE":
        return u in ["ELICE", "ELISE", "ELICE SVENSSON", "ELISE SVENSSON", "SVENSSON"]
    elif t == "1500":
        return u in ["1500", "15:00", "15.00", "KL 15:00", "KL. 15:00", "15 00", "15"]
    elif t == "42":
        return u in ["42", "SKOSTORLEK 42", "STORLEK 42"]
    elif t == "HÖGER":
        return u in ["HÖGER", "HÖGERHÄNT", "HÖGER-HÄNT"]
    return u == t

